 static Dictionary<string,object> OwnerInspection(IntPtr request,IntPtr ack,IntPtr view,IntPtr window,PI pi,long start,string output){
  Owned(window,pi,start);Require(WaitForSingleObject(ack,0)==258,"ACK must initially be unsignaled");Require(SetEvent(request),"Owner query request");
  var clock=System.Diagnostics.Stopwatch.StartNew();bool signaled=false;
  while(clock.ElapsedMilliseconds<5000){Pump(window,pi,start,50);uint wait=WaitForSingleObject(ack,0);Require(wait==0||wait==258,"Owner ACK wait failed");if(wait==0){signaled=true;break;}}
  Require(signaled,"Owner query ACK deadline");Owned(window,pi,start);
  int count=Marshal.ReadInt32(view,0);Require(count>0&&count<=4088&&Marshal.ReadInt32(view,4)==0,"Owner payload header bound");byte[] bytes=new byte[count];Marshal.Copy(IntPtr.Add(view,8),bytes,0,count);
  string json=new UTF8Encoding(false,true).GetString(bytes);var serializer=new System.Web.Script.Serialization.JavaScriptSerializer();serializer.MaxJsonLength=4088;
  var value=serializer.Deserialize<Dictionary<string,object>>(json);Save(Path.Combine(output,"owner-inspection.json"),value);Require(value!=null&&Convert.ToInt32(value["schema"])==1&&(string)value["phase"]=="ime-owner-readonly","Owner payload domain");
  uint pid;uint tid=GetWindowThreadProcessId(window,out pid);Require(Convert.ToUInt32(value["process_id"])==pi.pid&&pid==pi.pid&&Convert.ToUInt32(value["thread_id"])==tid&&Convert.ToUInt64(value["hwnd"])==unchecked((ulong)window.ToInt64()),"Owner payload HWND/thread identity");
  Require((string)value["status"]=="PASS"||(string)value["status"]=="QUERY_FAILED","Owner query status");
  foreach(string key in new string[]{"composition_bytes","result_bytes"})if(value.ContainsKey(key)&&value[key]!=null)Require(Convert.ToInt32(value[key])>=0&&Convert.ToInt32(value[key])<=8192,"Owner IME byte count bound");
  Save(Path.Combine(output,"owner-inspection.json"),value);return value;
